import{_ as s,o as a,c as e,a2 as n}from"./chunks/framework.D66Xq0Kv.js";const k=JSON.parse('{"title":"6. Tensor Algebra and Index Notation","description":"","frontmatter":{},"headers":[],"relativePath":"spec/06-tensor-algebra.md","filePath":"spec/06-tensor-algebra.md","lastUpdated":null}'),t={name:"spec/06-tensor-algebra.md"};function l(p,i,h,d,o,r){return a(),e("div",null,[...i[0]||(i[0]=[n(`<h1 id="_6-tensor-algebra-and-index-notation" tabindex="-1">6. Tensor Algebra and Index Notation <a class="header-anchor" href="#_6-tensor-algebra-and-index-notation" aria-label="Permalink to &quot;6. Tensor Algebra and Index Notation&quot;">​</a></h1><h2 id="_6-1-motivation" tabindex="-1">6.1 Motivation <a class="header-anchor" href="#_6-1-motivation" aria-label="Permalink to &quot;6.1 Motivation&quot;">​</a></h2><p>Linnet adopts the useful part of Einstein/einsum notation while rejecting string-encoded mini-languages and implicit reductions.</p><p>The canonical source syntax exposes free indices and reduction indices directly to the parser and type checker.</p><h2 id="_6-2-tensor-comprehension" tabindex="-1">6.2 Tensor comprehension <a class="header-anchor" href="#_6-2-tensor-comprehension" aria-label="Permalink to &quot;6.2 Tensor comprehension&quot;">​</a></h2><p>A tensor comprehension is introduced by an indexed <code>let</code> binding:</p><div class="language-linnet vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">linnet</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;"> c[m, n] </span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">=</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">    sum</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">[k] a[m, k] </span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;"> b[k, n]</span></span></code></pre></div><p>The indices on the left-hand side are free output indices.</p><p>Reduction indices are explicitly introduced by a reduction expression.</p><h2 id="_6-3-no-implicit-summation" tabindex="-1">6.3 No implicit summation <a class="header-anchor" href="#_6-3-no-implicit-summation" aria-label="Permalink to &quot;6.3 No implicit summation&quot;">​</a></h2><p>The following is invalid:</p><div class="language-linnet vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">linnet</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;"> y[i] </span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;"> a[i, j] </span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;"> b[j]</span></span></code></pre></div><p>because <code>j</code> is neither an output index nor explicitly bound by a reduction.</p><p>The valid form is:</p><div class="language-linnet vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">linnet</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;"> y[i] </span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;"> sum</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">[j] a[i, j] </span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;"> b[j]</span></span></code></pre></div><h2 id="_6-4-index-domains" tabindex="-1">6.4 Index domains <a class="header-anchor" href="#_6-4-index-domains" aria-label="Permalink to &quot;6.4 Index domains&quot;">​</a></h2><p>An index obtains its domain from tensor axes it indexes.</p><div class="language-linnet vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">linnet</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;"> c[m, n] </span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;"> sum</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">[k] a[m, k] </span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;"> b[k, n]</span></span></code></pre></div><p>implies:</p><ul><li><code>m</code> has the domain of <code>a</code> axis 0;</li><li><code>k</code> must have a single compatible domain for <code>a</code> axis 1 and <code>b</code> axis 0;</li><li><code>n</code> has the domain of <code>b</code> axis 1.</li></ul><p>Conflicting domains are a static shape error.</p><h2 id="_6-5-repeated-indices-in-one-tensor" tabindex="-1">6.5 Repeated indices in one tensor <a class="header-anchor" href="#_6-5-repeated-indices-in-one-tensor" aria-label="Permalink to &quot;6.5 Repeated indices in one tensor&quot;">​</a></h2><p>Repeated indices in a single tensor expression select a diagonal; they do not imply reduction.</p><div class="language-linnet vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">linnet</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;"> d[i] </span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;"> a[i, i]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;"> t </span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;"> sum</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">[i] a[i, i]</span></span></code></pre></div><p>The corresponding dimensions MUST be provably equal.</p><h2 id="_6-6-shape-pack-indices" tabindex="-1">6.6 Shape-pack indices <a class="header-anchor" href="#_6-6-shape-pack-indices" aria-label="Permalink to &quot;6.6 Shape-pack indices&quot;">​</a></h2><p>A variadic index pack is written with lowercase <code>*name</code> inside a comprehension:</p><div class="language-linnet vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">linnet</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;"> y[</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">s, o] </span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">=</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">    sum</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">[i] x[</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">s, i] </span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;"> weight[o, i]</span></span></code></pre></div><p>The pack corresponds to a statically known sequence of tensor axes derived from a generic shape pack.</p><h2 id="_6-7-reductions" tabindex="-1">6.7 Reductions <a class="header-anchor" href="#_6-7-reductions" aria-label="Permalink to &quot;6.7 Reductions&quot;">​</a></h2><p>Initial built-in reduction forms:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>sum[i] expr</span></span>
<span class="line"><span>prod[i] expr</span></span>
<span class="line"><span>max[i] expr</span></span>
<span class="line"><span>min[i] expr</span></span>
<span class="line"><span>any[i] expr</span></span>
<span class="line"><span>all[i] expr</span></span></code></pre></div><p>Multiple axes:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>sum[i, j] expr</span></span></code></pre></div><p>The reduced expression extends as far to the right as possible, so <code>x + sum[i] a[i] * b[i]</code> reduces the whole product.</p><p>Reduction names are contextual rather than reserved. <code>sum</code>, <code>prod</code>, <code>max</code>, <code>min</code>, <code>any</code>, and <code>all</code> begin a reduction only when immediately followed by an index list (<code>sum[i]</code>) or an accumulator dtype and an index list (<code>sum&lt;f32&gt;[i]</code>). In every other position they are ordinary identifiers, so <code>max(A, B)</code> remains a call. A value with one of these names therefore cannot be indexed directly.</p><h2 id="_6-8-accumulation-dtype" tabindex="-1">6.8 Accumulation dtype <a class="header-anchor" href="#_6-8-accumulation-dtype" aria-label="Permalink to &quot;6.8 Accumulation dtype&quot;">​</a></h2><p>A numeric reduction may explicitly specify accumulator dtype:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>sum&lt;f32&gt;[d] cast&lt;f32&gt;(x[d]) * cast&lt;f32&gt;(y[d])</span></span></code></pre></div><p>Without an explicit accumulator dtype, accumulation uses the expression dtype. With one, the reduced expression MUST already have that dtype; the accumulator dtype never converts implicitly.</p><p><code>sum</code>, <code>prod</code>, <code>max</code>, and <code>min</code> reduce <code>Numeric</code> values; <code>any</code> and <code>all</code> reduce <code>bool</code> values.</p><p>An index variable is not a value: it may appear only as a tensor index. Use <code>iota(N)[i]</code> where the position itself is needed.</p><p>The result dtype of <code>sum&lt;T&gt;</code> and <code>prod&lt;T&gt;</code> is <code>T</code> unless explicitly converted afterward.</p><h2 id="_6-9-common-examples" tabindex="-1">6.9 Common examples <a class="header-anchor" href="#_6-9-common-examples" aria-label="Permalink to &quot;6.9 Common examples&quot;">​</a></h2><p>Matrix multiplication:</p><div class="language-linnet vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">linnet</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;"> c[m, n] </span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;"> sum</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">[k] a[m, k] </span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;"> b[k, n]</span></span></code></pre></div><p>Batched matrix multiplication:</p><div class="language-linnet vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">linnet</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;"> c[</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">b, m, n] </span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;"> sum</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">[k] a[</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">b, m, k] </span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;"> b[</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">b, k, n]</span></span></code></pre></div><p>Outer product:</p><div class="language-linnet vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">linnet</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;"> c[i, j] </span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;"> a[i] </span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;"> b[j]</span></span></code></pre></div><p>Transpose-like remapping:</p><div class="language-linnet vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">linnet</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;"> y[j, i] </span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;"> x[i, j]</span></span></code></pre></div><p>Trace:</p><div class="language-linnet vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">linnet</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;"> t </span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;"> sum</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">[i] a[i, i]</span></span></code></pre></div><p>Attention score contraction:</p><div class="language-linnet vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">linnet</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;"> score[b, h, q, k] </span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">=</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">    sum&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;">f32</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">[d]</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;">        cast</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;">f32</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">(query[b, h, q, d]) </span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">*</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;">        cast</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;">f32</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">(key[b, h, k, d])</span></span></code></pre></div><h2 id="_6-10-core-ir-lowering" tabindex="-1">6.10 Core IR lowering <a class="header-anchor" href="#_6-10-core-ir-lowering" aria-label="Permalink to &quot;6.10 Core IR lowering&quot;">​</a></h2><p>Tensor comprehensions lower to a generalized contraction/reduction representation in Core Tensor IR. The source syntax does not prescribe loop order, memory layout, tiling, or backend kernel choice.</p><p>A backend or optimizer is free to choose any semantically equivalent implementation permitted by the active numeric-equivalence policy.</p><h2 id="_6-11-compatibility-einsum" tabindex="-1">6.11 Compatibility <code>einsum</code> <a class="header-anchor" href="#_6-11-compatibility-einsum" aria-label="Permalink to &quot;6.11 Compatibility \`einsum\`&quot;">​</a></h2><p>A future compatibility library MAY provide a string-based <code>einsum</code> parser, but it is not canonical language syntax and MUST lower immediately to the same typed tensor-algebra representation.</p>`,61)])])}const g=s(t,[["render",l]]);export{k as __pageData,g as default};
